        module.fail_json(msg='Missing GCE connection parameters in libcloud secrets file.')
        return None
    else:
        try:
            with open(credentials_file) as credentials:
                json.loads(credentials.read())
            if LooseVersion(libcloud.__version__) < '0.17.0':
                module.fail_json(msg='Using JSON credentials but libcloud minimum version not met. Upgrade to libcloud>=0.17.0.')
                return None
        except ValueError as e:
            pass
    if provider is None:
        provider = Provider.GCE
    try:
        gce = get_driver(provider)(service_account_email, credentials_file, datacenter=module.params.get('zone', None), project=project_id)
        gce.connection.user_agent_append('%s/%s' % (USER_AGENT_PRODUCT, USER_AGENT_VERSION))
    except (RuntimeError, ValueError) as e:
        module.fail_json(msg=str(e), changed=False)
    except Exception as e:
        module.fail_json(msg=unexpected_error_msg(e), changed=False)
    return gce

